/* Palette: #1e293b (dark), #f8fafc (light), #38bdf8 (accent), #f472b6 (secondary), #fbbf24 (tertiary) */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

[hidden] {
  display: none !important;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 18px;
  line-height: 1.5;
  background: #1e293b;
  color: #f8fafc;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
}

.gallery {
  width: 100%;
  max-width: 900px;
  text-align: center;
}

h1 {
  font-size: 2rem;
  margin-bottom: 8px;
  color: #38bdf8;
  letter-spacing: 0.5px;
}

.subtitle {
  color: #94a3b8;
  margin-bottom: 32px;
  font-size: 1rem;
}

.grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
  gap: 20px;
  padding: 8px;
}

.tile {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  padding: 16px;
  background: #334155;
  border: 2px solid transparent;
  border-radius: 16px;
  cursor: pointer;
  color: #f8fafc;
  font-size: 1rem;
  font-family: inherit;
  transition: transform 0.15s ease, border-color 0.15s ease, background 0.15s ease;
}

.tile:hover {
  background: #475569;
  transform: translateY(-3px);
  border-color: #38bdf8;
}

.tile:focus-visible {
  outline: 3px solid #38bdf8;
  outline-offset: 3px;
}

.tile:active {
  transform: scale(0.97);
  background: #1e293b;
}

.art {
  width: 100%;
  aspect-ratio: 1 / 1;
  border-radius: 12px;
  position: relative;
  overflow: hidden;
  display: block;
}

/* Sunset */
.art-sunset {
  background: linear-gradient(to bottom, #f472b6 0%, #fbbf24 100%);
}
.art-sunset::after {
  content: '';
  position: absolute;
  bottom: 20%;
  left: 50%;
  width: 40%;
  height: 40%;
  background: #fbbf24;
  border-radius: 50%;
  transform: translateX(-50%);
  box-shadow: 0 0 0 10px rgba(251, 191, 36, 0.3);
}

/* Ocean */
.art-ocean {
  background: linear-gradient(to bottom, #38bdf8 0%, #1e293b 100%);
}
.art-ocean::before {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;
  height: 40%;
  background: #0ea5e9;
  clip-path: polygon(0 40%, 25% 0, 50% 40%, 75% 0, 100% 40%, 100% 100%, 0 100%);
}

/* Forest */
.art-forest {
  background: #166534;
}
.art-forest::before {
  content: '';
  position: absolute;
  bottom: 0;
  left: 10%;
  width: 30%;
  height: 70%;
  background: #22c55e;
  clip-path: polygon(50% 0, 100% 100%, 0 100%);
}
.art-forest::after {
  content: '';
  position: absolute;
  bottom: 0;
  right: 10%;
  width: 40%;
  height: 90%;
  background: #16a34a;
  clip-path: polygon(50% 0, 100% 100%, 0 100%);
}

/* Desert */
.art-desert {
  background: #fbbf24;
}
.art-desert::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;
  height: 50%;
  background: #d97706;
  clip-path: polygon(0 100%, 20% 40%, 40% 70%, 60% 30%, 80% 60%, 100% 20%, 100% 100%);
}

/* Night */
.art-night {
  background: #0f172a;
}
.art-night::before {
  content: '';
  position: absolute;
  top: 20%;
  left: 30%;
  width: 20%;
  height: 20%;
  background: #f8fafc;
  border-radius: 50%;
  box-shadow: 30px 10px 0 #fbbf24, 10px 30px 0 #38bdf8;
}

/* Candy */
.art-candy {
  background: repeating-linear-gradient(45deg, #f472b6, #f472b6 10px, #f8fafc 10px, #f8fafc 20px);
}
.art-candy::after {
  content: '';
  position: absolute;
  top: 50%;
  left: 50%;
  width: 50%;
  height: 50%;
  background: #fbbf24;
  border-radius: 50%;
  transform: translate(-50%, -50%);
}

.tile-title {
  font-weight: 600;
  font-size: 1rem;
}

/* Modal */
.modal {
  position: fixed;
  inset: 0;
  z-index: 100;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.modal-backdrop {
  position: absolute;
  inset: 0;
  background: rgba(15, 23, 42, 0.8);
}

.modal-content {
  position: relative;
  background: #1e293b;
  border: 2px solid #38bdf8;
  border-radius: 24px;
  padding: 24px;
  max-width: 480px;
  width: 100%;
  text-align: center;
  box-shadow: 0 20px 40px rgba(0, 0, 0, 0.5);
}

.modal-title {
  font-size: 1.5rem;
  margin-bottom: 16px;
  color: #38bdf8;
}

.modal-art {
  width: 100%;
  aspect-ratio: 1 / 1;
  border-radius: 16px;
  margin-bottom: 24px;
  background: #334155;
  overflow: hidden;
  position: relative;
}

/* Reuse art styles inside modal */
.modal-art .art {
  width: 100%;
  height: 100%;
  border-radius: 0;
}

.modal-controls {
  display: flex;
  gap: 12px;
  justify-content: center;
  flex-wrap: wrap;
}

.btn {
  font-family: inherit;
  font-size: 1rem;
  padding: 12px 24px;
  border-radius: 12px;
  border: 2px solid #38bdf8;
  background: transparent;
  color: #f8fafc;
  cursor: pointer;
  transition: background 0.15s ease, transform 0.1s ease;
  min-width: 100px;
}

.btn:hover {
  background: #38bdf8;
  color: #1e293b;
}

.btn:focus-visible {
  outline: 3px solid #fbbf24;
  outline-offset: 3px;
}

.btn:active {
  transform: scale(0.95);
}

.btn-close {
  border-color: #f472b6;
}

.btn-close:hover {
  background: #f472b6;
  color: #1e293b;
}

@media (max-width: 480px) {
  body {
    padding: 16px;
  }
  h1 {
    font-size: 1.6rem;
  }
  .grid {
    grid-template-columns: repeat(2, 1fr);
    gap: 12px;
  }
  .modal-content {
    padding: 16px;
  }
  .btn {
    padding: 10px 16px;
    font-size: 0.95rem;
    min-width: 80px;
  }
}

(function () {
  'use strict';

  const tiles = Array.from(document.querySelectorAll('.tile'));
  const modal = document.getElementById('modal');
  const modalTitle = document.getElementById('modal-title');
  const modalArt = document.getElementById('modal-art');
  const prevBtn = document.getElementById('prev-btn');
  const nextBtn = document.getElementById('next-btn');
  const closeBtn = document.getElementById('close-btn');
  const backdrop = modal.querySelector('.modal-backdrop');

  const titles = ['Sunset', 'Ocean', 'Forest', 'Desert', 'Night', 'Candy'];
  const artClasses = ['art-sunset', 'art-ocean', 'art-forest', 'art-desert', 'art-night', 'art-candy'];

  let currentIndex = 0;
  let lastFocused = null;

  function openModal(index) {
    currentIndex = index;
    lastFocused = document.activeElement;
    updateModal();
    modal.hidden = false;
    closeBtn.focus();
  }

  function closeModal() {
    modal.hidden = true;
    if (lastFocused) {
      lastFocused.focus();
    }
  }

  function updateModal() {
    modalTitle.textContent = titles[currentIndex];
    modalArt.innerHTML = '<div class="art ' + artClasses[currentIndex] + '"></div>';
    prevBtn.disabled = currentIndex === 0;
    nextBtn.disabled = currentIndex === titles.length - 1;
  }

  function showPrev() {
    if (currentIndex > 0) {
      currentIndex--;
      updateModal();
    }
  }

  function showNext() {
    if (currentIndex < titles.length - 1) {
      currentIndex++;
      updateModal();
    }
  }

  tiles.forEach(function (tile) {
    tile.addEventListener('click', function () {
      const index = parseInt(tile.getAttribute('data-index'), 10);
      openModal(index);
    });
  });

  prevBtn.addEventListener('click', showPrev);
  nextBtn.addEventListener('click', showNext);
  closeBtn.addEventListener('click', closeModal);
  backdrop.addEventListener('click', closeModal);

  document.addEventListener('keydown', function (e) {
    if (modal.hidden) return;
    if (e.key === 'Escape') {
      e.preventDefault();
      closeModal();
    } else if (e.key === 'ArrowLeft') {
      e.preventDefault();
      showPrev();
    } else if (e.key === 'ArrowRight') {
      e.preventDefault();
      showNext();
    }
  });

  // Trap focus inside modal
  modal.addEventListener('keydown', function (e) {
    if (e.key !== 'Tab') return;
    const focusable = modal.querySelectorAll('button:not([disabled])');
    if (focusable.length === 0) return;
    const first = focusable[0];
    const last = focusable[focusable.length - 1];
    if (e.shiftKey) {
      if (document.activeElement === first) {
        e.preventDefault();
        last.focus();
      }
    } else {
      if (document.activeElement === last) {
        e.preventDefault();
        first.focus();
      }
    }
  });
})();
